const cfg = $input.first().json;
const chunks = [];

const fmtIso = (d) => {
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const day = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
};

const hoje = new Date();
hoje.setUTCHours(0, 0, 0, 0);

if (cfg.modo_backfill === true) {
  // MODO BACKFILL: Fatiado em chunks de 7 dias desde 01/01/2026 com todas=S
  const inicio = new Date('2026-01-01T00:00:00Z');
  const tamanhoChunk = cfg.tamanho_chunk_dias || 7;

  let cursor = new Date(inicio);
  while (cursor <= hoje) {
    const fim = new Date(cursor);
    fim.setUTCDate(fim.getUTCDate() + tamanhoChunk - 1);
    if (fim > hoje) fim.setTime(hoje.getTime());

    chunks.push({
      json: {
        ...cfg,
        chunk_dtini_iso: fmtIso(cursor),
        chunk_dtfim_iso: fmtIso(fim),
        usar_todas: true,
        is_diario: false
      }
    });

    cursor = new Date(fim);
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }
} else {
  // MODO DIÁRIO DE PRODUÇÃO: Janela retroativa de D-15 até hoje com todas=N
  const inicioDiario = new Date(hoje);
  inicioDiario.setUTCDate(inicioDiario.getUTCDate() - 15);

  chunks.push({
    json: {
      ...cfg,
      chunk_dtini_iso: fmtIso(inicioDiario),
      chunk_dtfim_iso: fmtIso(hoje),
      usar_todas: false,
      is_diario: true
    }
  });
}

return chunks;

const cfg = $input.first().json;
const token = $('POST /auth (Login)').first().json.token;

if (!token) {
  throw new Error('Token não encontrado no retorno do /auth');
}

// Em modo backfill usa todas=S; em modo diário usa todas=N
const todasFlag = cfg.usar_todas ? 'S' : 'N';
const url = `${cfg.url_base}/NotaFiscal/Vinculo?dtIni=${cfg.chunk_dtini_iso}&dtFim=${cfg.chunk_dtfim_iso}&todas=${todasFlag}`;

return [{
  json: {
    ...cfg,
    token,
    url_final: url,
    bearer_header: `Bearer ${token}`,
    chunk_inicio_ts: Date.now()
  }
}];

// Coletar todos os items que chegaram do GET (array no root da API)
const items = $input.all();
const vinculos = items.map(i => i.json).filter(v => v && v.IdTransacao);

if (vinculos.length === 0) return [];

// Mapa API (PascalCase) -> coluna do banco (snake_case)
// CORRIGIDO: incluídos numero_nfe, valor_total, data_emissao, cnpj_destinatario
// e 'Operacao' com O maiúsculo (é assim que a API envia).
const mapa = {
  IdTransacao:      'id_transacao',
  ChaveNFe:         'chave_nfe',
  NumeroNFe:        'numero_nfe',
  VlTotal:          'valor_total',
  DtEmissao:        'data_emissao',
  CnpjDestinatario: 'cnpj_destinatario',
  VctoPrevisto:     'vencimento_previsto',
  Operacao:         'operacao'
};

const colunas = Object.values(mapa);
const colunasData    = new Set(['data_emissao', 'vencimento_previsto']); // ::timestamptz
const colunasNumeric = new Set(['valor_total']);                          // ::numeric

// Dedup pelo id_transacao (chave única); última ocorrência prevalece
const seen = new Map();
for (const v of vinculos) {
  const obj = {};
  for (const [api, db] of Object.entries(mapa)) {
    obj[db] = v[api] !== undefined ? v[api] : null;
  }
  seen.set(String(obj.id_transacao), obj);
}
const dedup = Array.from(seen.values());

const CHUNK = 500;
const chunks = [];
for (let i = 0; i < dedup.length; i += CHUNK) chunks.push(dedup.slice(i, i + CHUNK));

const escapar = (v, col) => {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (colunasData.has(col)) {
    return `'${String(v).replace(/'/g, "''")}'::timestamptz`;
  }
  if (colunasNumeric.has(col)) {
    // troca vírgula decimal por ponto, por segurança de locale
    const num = String(v).replace(',', '.').replace(/'/g, "''");
    return `'${num}'::numeric`;
  }
  return `'${String(v).replace(/'/g, "''")}'`;
};

const conflictCol = 'id_transacao';
const updateSet = colunas
  .filter(c => c !== conflictCol)
  .map(c => `"${c}" = EXCLUDED."${c}"`)
  .join(',\n  ');

const result = [];
for (const chunk of chunks) {
  const values = chunk.map(row => {
    const vals = colunas.map(c => escapar(row[c], c));
    return `(${vals.join(', ')}, NOW(), NULL)`;
  }).join(',\n');

  const sql = `INSERT INTO torre.integration_truckpag_nfe_vinculos (
  ${colunas.map(c => `"${c}"`).join(', ')},
  created_at,
  updated_at
)
VALUES ${values}
ON CONFLICT ("${conflictCol}") DO UPDATE SET
  ${updateSet},
  updated_at = NOW();`.trim();

  result.push({
  json: { sql, qtd_registros: chunk.length },
  pairedItem: { item: 0 }
});
}

return result;

// Acumula estatísticas do run via Static Data (persiste entre iterações do loop)
const sd = $getWorkflowStaticData('global');
const cfg = $('Loop Over Chunks').item.json;

// Reinicia contadores se for um novo run (detecta via run_inicio_ts)
if (!sd.run_inicio_ts || sd.run_inicio_ts !== cfg.run_inicio_ts) {
  sd.run_inicio_ts   = cfg.run_inicio_ts;
  sd.chunks_ok       = 0;
  sd.chunks_vazio    = 0;
  sd.chunks_erro     = 0;
  sd.total_registros = 0;
  sd.run_inicio_iso  = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
}

const status = $input.first().json._acumula_status ?? 'sucesso';
const qtd    = $input.first().json._acumula_qtd    ?? 0;

if (status === 'sucesso') {
  sd.chunks_ok++;
  sd.total_registros += qtd;
} else if (status === 'vazio') {
  sd.chunks_vazio++;
} else if (status === 'erro') {
  sd.chunks_erro++;
}

return [{
  json: {
    ...$input.first().json,
    stats: {
      chunks_ok:       sd.chunks_ok,
      chunks_vazio:    sd.chunks_vazio,
      chunks_erro:     sd.chunks_erro,
      total_registros: sd.total_registros,
      run_inicio_iso:  sd.run_inicio_iso
    }
  }
}];
